  // the Timing step marking the field required in the first place.
  const scheduleStepProblem = (step) => {
    if (step === 1 && !scheduleForm.name.trim()) return 'Give the schedule a name before continuing.';
    if (step === 2) return getScheduleTimingProblem(scheduleForm, { timeRange, weekDays, selectedMonths, monthDays });
    return null;
  };

  const handleCreateSchedule = async (e) => {
    e.preventDefault();
    if (isCreatingSchedule) return;

    let sourceSequenceId = loadedSavedSequenceId || null;

    // Validate required fields
    if (!scheduleForm.name.trim()) {
      alert('Schedule name is required');
      return;
    }
    if (!scheduleForm.start_date && !['monthly', 'yearly'].includes(scheduleForm.type)) {
      alert('Start date is required');
      return;
    }

    // Validate recurrence patterns
    if (!validateScheduleRecurrence()) return;

    // Advanced mode: validate sequence and save to library
    if (scheduleMode === 'advanced') {
      // Ensure sequenceBlocks is an array
      const blocks = Array.isArray(sequenceBlocks) ? sequenceBlocks : [];
      console.log('Schedule Mode:', scheduleMode);
      console.log('Sequence Blocks (raw):', sequenceBlocks);
      console.log('Sequence Blocks (validated):', blocks);
      console.log('Blocks length:', blocks.length);
      
      if (blocks.length === 0) {
        alert('Please add at least one block to the sequence before creating the schedule.\n\nUse the "Add Random Block" or "Add Fixed Block" buttons in the Sequence Builder section above to create your sequence.');
        return;
      }
      const validation = validateSequence(blocks, categories, prerolls);
      console.log('Validation result:', validation);
      
      if (!validation.valid) {
        alert('Sequence validation failed:\n' + validation.errors.join('\n'));
        return;
      }

      // Only save sequence to library if NOT using an already-saved sequence
      if (!loadedSavedSequenceId) {
        try {
          const sequenceName = scheduleForm.name.trim() + ' Sequence';
          const sequenceDescription = `Sequence for schedule "${scheduleForm.name.trim()}"`;
          console.log('Saving sequence to library:', sequenceName);
          const savedSequence = await saveSequence(sequenceName, sequenceDescription, {
            preserveBuilder: true,
            forceCreate: true
          });
          sourceSequenceId = savedSequence?.id ?? null;
          if (sourceSequenceId) setLoadedSavedSequenceId(sourceSequenceId);
        } catch (error) {
          console.error('Failed to save sequence to library:', error);
          // Continue anyway - sequence will still be saved in the schedule
        }
      } else {
        console.log('Using existing saved sequence ID:', loadedSavedSequenceId, '- skipping library save');
      }
    } else {
      // Simple mode: validate category
      if (!scheduleForm.category_id) {
        alert('Please select a category');
        return;
      }

      // Ensure category_id is valid
      const categoryId = parseInt(scheduleForm.category_id);
      if (isNaN(categoryId) || categoryId <= 0) {
        alert('Please select a valid category');
        return;
      }
    }

    const scheduleData = buildScheduleData();

    // Add category_id for simple mode, sequence for advanced mode
    if (scheduleMode === 'simple') {
      scheduleData.category_id = parseInt(scheduleForm.category_id);
    } else {
      // Use validated blocks array
      const blocks = Array.isArray(sequenceBlocks) ? sequenceBlocks : [];
      scheduleData.sequence = stringifySequence(blocks);
      // Backend expects category_id, so use the first category-backed sequence block or null.
      const firstCategory = blocks.find(b => ['random', 'sequential'].includes(b.type))?.category_id;
      scheduleData.category_id = firstCategory || null;
      // Link to the saved sequence (if this was built from one) so edits to that
      // sequence propagate back into this schedule.
      if (sourceSequenceId) {
        scheduleData.source_sequence_id = sourceSequenceId;
      }
    }

    setIsCreatingSchedule(true);
    fetch(apiUrl('schedules'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(scheduleData)
    })
      .then(res => {
        if (!res.ok) {
          return res.text().then(text => {
            throw new Error(`HTTP ${res.status}: ${text}`);
          });
        }
        return res.json();
      })
      .then(data => {
        // Check for potential conflicts with the new schedule
        const newSchedule = { ...data, ...scheduleData };
        const potentialConflicts = getScheduleConflicts(newSchedule);

        if (potentialConflicts.length > 0) {
          const conflictNames = potentialConflicts.map(c => c.schedule.name).join(', ');
          showAlert(`"${scheduleData.name}" created, but it overlaps ${conflictNames} at the same priority. Give them different priorities to control which wins.`, 'warning');
        } else {
          setAlertDialog({ open: true, title: 'Schedule created', type: 'success', message: `"${scheduleData.name}" is saved and will run on its schedule. The form has been cleared for the next one.` });
        }

        localStorage.removeItem('nx_schedule_draft');
        setScheduleForm({
          name: '', type: 'monthly', start_date: '', end_date: '',
          category_id: '', playlist: false, fallback_category_id: '', color: '',
          holiday_name: '', holiday_country: '', blend_enabled: false, priority: 5, exclusive: false
        });
        setScheduleMode('simple');
        setSequenceBlocks([]);
        setLoadedSavedSequenceId(null);
        setWeekDays([]);
        setSelectedMonths([]); setMonthDays([]);
        setTimeRange({ start: '', end: '' });
        // Always refresh from the server: the raw POST response doesn't carry
        // every field (recurrence_pattern, etc.) that conflict detection needs,
        // so an optimistic local append left new schedules invisible to the
        // conflicts page until a manual refresh.
        fetchData();
        // Land on the list, where the new schedule is. Clearing the wizard in
        // place left a blank "Untitled schedule" on screen, which looks exactly
        // like a click that did nothing - and invites a second click that
        // creates a duplicate. Showing the result is the confirmation.
        setActiveTab('schedules');
      })
      .catch(error => {
        console.error('Schedule creation error:', error);
        showAlert('Could not create the schedule: ' + error.message, 'error');
      })
      .finally(() => {
        setIsCreatingSchedule(false);
      });
  };


