  // ========== Schedule Conflict Detection ==========
  
  // ========== Unified Day Conflict State ==========
  // This is the single source of truth for conflict detection across ALL views.
  // Matches the backend scheduler logic in scheduler.py _check_and_execute_schedules().
  //
  // BACKEND RULES:
  //   1. Exclusive schedules ALWAYS win over everything (no blending possible)
  //      - If multiple exclusives: highest priority wins, then earliest end_date, then lowest id
  //   2. If no exclusive: check for blend mode (2+ blend_enabled schedules → blend together)
  //   3. If no exclusive, no blend: highest priority wins (normal deterministic selection)
  //
  // CONFLICT DEFINITION (when user action is needed):
  //   TRUE CONFLICT = two or more winner candidates share the highest active
  //   priority after exclusive and blend rules have been applied for that time.
  //   Everything else is deterministic and handled by the priority system:
  //     - Different-priority exclusives → higher wins (by design)
  //     - Exclusive vs non-exclusive → exclusive wins (by design)
  //     - Non-exclusive priority differences → higher wins (by design)
  //     - Blend mode → all blend together (by design)
  //     - Exclusive with time range → wins during its window, non-exclusive schedules
  //       run outside that window (by design, not a conflict)
  //
  // WHAT IS NOT A CONFLICT:
  //   - Different priorities (higher always wins deterministically)
  //   - Exclusive blocking non-exclusive (that's what exclusive MEANS)
  //   - Two or more simultaneously active blend-enabled schedules
  //   - Schedules with non-overlapping time ranges
  //   - Fallback/filler categories (only play when nothing else is active)
  //
  const buildActionableConflictDaysByPair = (candidateSchedules, lookaheadDays, startDate) => {
    const normalizeDay = (dateStr) => {
      if (!dateStr) return null;
      const date = new Date(dateStr);
      return new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
    };
    const rangeStart = startDate ? new Date(startDate) : new Date();
    const firstDay = new Date(
      rangeStart.getFullYear(),
      rangeStart.getMonth(),
      rangeStart.getDate()
    );
    const conflictDaysByPair = new Map();

    for (let dayOffset = 0; dayOffset < lookaheadDays; dayOffset += 1) {
      const occurrences = [];
      for (const relativeAnchorOffset of [-1, 0]) {
        const anchorDay = new Date(
          firstDay.getFullYear(),
          firstDay.getMonth(),
          firstDay.getDate() + dayOffset + relativeAnchorOffset
        );
        candidateSchedules.forEach(schedule => {
          if (!isScheduleActiveOnDay(schedule, anchorDay.getTime(), normalizeDay)) return;
          occurrences.push(buildScheduleTimeOccurrence(schedule, relativeAnchorOffset));
        });
      }

      const segmentState = evaluateScheduleOccurrenceSegments(occurrences);
      if (!segmentState.hasConflict) continue;
      const conflictDay = new Date(
        firstDay.getFullYear(),
        firstDay.getMonth(),
        firstDay.getDate() + dayOffset
      );
      segmentState.conflictPairs.forEach(pair => {
        if (!conflictDaysByPair.has(pair.key)) conflictDaysByPair.set(pair.key, []);
        conflictDaysByPair.get(pair.key).push(conflictDay);
      });
    }

    return conflictDaysByPair;
  };

  const computeDayConflictState = (contentScheds) => {
    const segmentState = evaluateScheduleTimeSegments(contentScheds);
    // Exclusive schedules
    const exclusiveScheds = contentScheds.filter(s => s.exclusive);
    const hasExclusive = exclusiveScheds.length > 0;

    // Check if ALL exclusive schedules have time restrictions
    const exclusiveHasTimeRange = hasExclusive && exclusiveScheds.every(s => {
      if (!s.recurrence_pattern) return false;
      try {
        const pattern = JSON.parse(s.recurrence_pattern);
        return pattern.timeRange?.start ? true : false;
      } catch (e) { return false; }
    });

    // Non-exclusive schedules
    const nonExclusiveScheds = contentScheds.filter(s => !s.exclusive);
    const actualBlendIds = new Set(segmentState.blendScheduleIds);
    const blendScheds = nonExclusiveScheds.filter(s => actualBlendIds.has(s.id));

    // Blend mode detection:
    // - When no exclusive: 2+ blend_enabled non-exclusive schedules
    // - When exclusive has time range: 2+ blend_enabled operate outside the exclusive window
    const hasBlend = segmentState.hasBlend;

    // Segment-level state mirrors the backend decision at every active minute,
    // including exclusive precedence and group-based blend mode.
    const hasConflict = segmentState.hasConflict;
    const samePriorityExclusiveConflict = segmentState.conflictPairs.some(
      pair => pair.mode === 'exclusive'
    );

    // Winner determination (matches backend scheduler.py logic)
    let winner = null;
    let nonExclusiveWinner = null;

    if (contentScheds.length > 0) {
      const prioritySort = (a, b) => {
        const pA = a.priority ?? 5; const pB = b.priority ?? 5;
        if (pA !== pB) return pB - pA;
        const eA = a.end_date ? new Date(a.end_date).getTime() : Number.MAX_SAFE_INTEGER;
        const eB = b.end_date ? new Date(b.end_date).getTime() : Number.MAX_SAFE_INTEGER;
        if (eA !== eB) return eA - eB;
        const sA = a.start_date ? new Date(a.start_date).getTime() : 0;
        const sB = b.start_date ? new Date(b.start_date).getTime() : 0;
        if (sA !== sB) return sA - sB;
        return a.id - b.id;
      };

      // Exclusive winner selection intentionally omits start date; this mirrors
      // scheduler.py's priority -> earliest end -> lowest id order.
      const exclusivePrioritySort = (a, b) => {
        const pA = a.priority ?? 5; const pB = b.priority ?? 5;
        if (pA !== pB) return pB - pA;
        const eA = a.end_date ? new Date(a.end_date).getTime() : Number.MAX_SAFE_INTEGER;
        const eB = b.end_date ? new Date(b.end_date).getTime() : Number.MAX_SAFE_INTEGER;
        if (eA !== eB) return eA - eB;
        return a.id - b.id;
      };

      if (hasExclusive) {
        // Exclusive wins
        const sorted = [...exclusiveScheds].sort(exclusivePrioritySort);
        winner = sorted[0];

        // If exclusive has time range, also compute non-exclusive winner
        if (exclusiveHasTimeRange && nonExclusiveScheds.length > 0) {
          if (hasBlend) {
            nonExclusiveWinner = 'blend';
          } else if (nonExclusiveScheds.length === 1) {
            nonExclusiveWinner = nonExclusiveScheds[0];
          } else {
            const nonExSorted = [...nonExclusiveScheds].sort(prioritySort);
            nonExclusiveWinner = nonExSorted[0];
          }
        }
      } else if (hasBlend) {
        // Blend mode - blending scheds are all "winners"
        winner = blendScheds[0]; // Nominal winner for tracking
        nonExclusiveWinner = 'blend';
      } else {
        // Normal priority selection
        const sorted = [...contentScheds].sort(prioritySort);
        winner = sorted[0];
      }
    }

    return {
      hasConflict,
      samePriorityExclusiveConflict,
      hasBlend,
      hasExclusive,
      exclusiveHasTimeRange,
      exclusiveScheds,
      nonExclusiveScheds,
      blendScheds,
      winner,
      nonExclusiveWinner
    };
  };
  
  // Check if a schedule has equal-priority overlaps that should be made explicit
  const scheduleConflictPairCache = React.useMemo(
    () => ({ source: schedules, byYear: new Map() }),
    [schedules]
  ).byYear;
  const getActionableConflictDaysForSchedule = (schedule) => {
    const currentYear = new Date().getFullYear();
    const configuredStart = schedule?.start_date ? new Date(schedule.start_date) : null;
    const configuredYear = configuredStart && !Number.isNaN(configuredStart.getTime())
      ? configuredStart.getFullYear()
      : currentYear;
    // Year 2000 is the sentinel used for year-agnostic yearly schedules.
    const analysisYear = configuredYear !== 2000 && configuredYear > currentYear
      ? configuredYear
      : currentYear;
    const analysisStart = new Date(analysisYear, 0, 1);
    // One complete recurrence year plus the following January covers every
    // weekday/month and concrete windows that cross New Year without making
    // repeated tooltip checks scan multiple full years.
    const analysisEnd = new Date(analysisYear + 1, 1, 1);
    const lookaheadDays = Math.round(
      (analysisEnd.getTime() - analysisStart.getTime()) / (24 * 60 * 60 * 1000)
    );
    const scheduleIsLoaded = schedules.some(candidate => candidate.id === schedule.id);
    if (!scheduleIsLoaded) {
      return buildActionableConflictDaysByPair(
        [...schedules.filter(candidate => candidate.is_active), schedule],
        lookaheadDays,
        analysisStart
      );
    }
    if (!scheduleConflictPairCache.has(analysisYear)) {
      scheduleConflictPairCache.set(analysisYear, buildActionableConflictDaysByPair(
        schedules.filter(candidate => candidate.is_active),
        lookaheadDays,
        analysisStart
      ));
    }
    return scheduleConflictPairCache.get(analysisYear);
  };

  const getScheduleConflicts = (schedule) => {
    if (!schedule) return [];
    if (!schedule.is_active) return [];
    if (!schedule.start_date) return []; // No start date = not visible on calendar
    
    const conflicts = [];
    
    // Parse this schedule's recurrence pattern
    let thisPattern = {};
    try {
      thisPattern = schedule.recurrence_pattern ? JSON.parse(schedule.recurrence_pattern) : {};
    } catch (e) {
      thisPattern = {};
    }
    
    const thisWeekDays = thisPattern.weekDays || [];
    const thisTimeRange = thisPattern.timeRange || {};
    
    // Normalize priority (default to 5 if not set)
    const thisPriority = schedule.priority ?? 5;
    const actionableConflictDays = getActionableConflictDaysForSchedule(schedule);

    // Check against all other schedules
    schedules.forEach(other => {
      if (other.id === schedule.id) return; // Skip self
      if (!other.is_active) return; // Inactive schedules don't conflict
      if (!other.start_date) return; // No start date = not visible on calendar
      
      // Scenario 1: Both exclusive, same priority (winner depends on tie-break fields)
      if (schedule.exclusive && other.exclusive) {
        const otherPriority = other.priority ?? 5;
        if (otherPriority !== thisPriority) return; // Different priorities = deterministic
      }
      // Scenario 2: Both non-exclusive, both non-blend, same priority
      else if (!schedule.exclusive && !other.exclusive && !isEffectiveBlendPair(schedule, other)) {
        const otherPriority = other.priority ?? 5;
        if (otherPriority !== thisPriority) return; // Different priorities = deterministic
      }
      // All other scenarios are deterministic (not conflicts)
      else {
        return;
      }
      if (!actionableConflictDays.has(getSchedulePairKey(schedule, other))) return;
      
      // Parse other schedule's recurrence pattern
      let otherPattern = {};
      try {
        otherPattern = other.recurrence_pattern ? JSON.parse(other.recurrence_pattern) : {};
      } catch (e) {
        otherPattern = {};
      }
      
      const otherWeekDays = otherPattern.weekDays || [];
      const otherTimeRange = otherPattern.timeRange || {};
      
      // Check if both are weekly schedules with overlapping days
      if (schedule.type === 'weekly' && other.type === 'weekly') {
        const overlappingDays = thisWeekDays.filter(d => otherWeekDays.includes(d));
        if (overlappingDays.length === 0) return; // No common days
        
        // Check time range overlap
        if (timeRangesOverlap(
          thisTimeRange.start, thisTimeRange.end,
          otherTimeRange.start, otherTimeRange.end
        )) {
          conflicts.push({
            schedule: other,
            overlappingDays,
            thisTime: thisTimeRange,
            otherTime: otherTimeRange
          });
        }
      }
      
      // Check if both are daily schedules
      else if (schedule.type === 'daily' && other.type === 'daily') {
        // Check date range overlap
        const thisStart = schedule.start_date ? new Date(schedule.start_date) : new Date(0);
        const thisEnd = schedule.end_date ? new Date(schedule.end_date) : new Date('2099-12-31');
        const otherStart = other.start_date ? new Date(other.start_date) : new Date(0);
        const otherEnd = other.end_date ? new Date(other.end_date) : new Date('2099-12-31');
        
        if (thisStart <= otherEnd && otherStart <= thisEnd) {
          // Date ranges overlap, check time ranges
          if (timeRangesOverlap(
            thisTimeRange.start, thisTimeRange.end,
            otherTimeRange.start, otherTimeRange.end
          )) {
            conflicts.push({
              schedule: other,
              thisTime: thisTimeRange,
              otherTime: otherTimeRange
            });
          }
        }
      }
      
      // Check if both are monthly schedules with overlapping months
      else if (schedule.type === 'monthly' && other.type === 'monthly') {
        const thisMonths = thisPattern.months || [];
        const otherMonths = otherPattern.months || [];
        const overlappingMonths = thisMonths.filter(m => otherMonths.includes(m));
        if (thisMonths.length > 0 && otherMonths.length > 0 && overlappingMonths.length === 0) return;

        const thisStart = schedule.start_date ? new Date(schedule.start_date) : new Date(0);
        const thisEnd = schedule.end_date ? new Date(schedule.end_date) : new Date('2099-12-31');
        const otherStart = other.start_date ? new Date(other.start_date) : new Date(0);
        const otherEnd = other.end_date ? new Date(other.end_date) : new Date('2099-12-31');

        if (thisStart <= otherEnd && otherStart <= thisEnd) {
          if (timeRangesOverlap(
            thisTimeRange.start, thisTimeRange.end,
            otherTimeRange.start, otherTimeRange.end
          )) {
            conflicts.push({
              schedule: other,
              overlappingDays: overlappingMonths,
              thisTime: thisTimeRange,
              otherTime: otherTimeRange,
              note: 'Monthly schedules overlap on same month(s)'
            });
          }
        }
      }
      
      // Check yearly/holiday vs yearly/holiday — date window overlap (month+day)
      else if (['yearly', 'holiday'].includes(schedule.type) && ['yearly', 'holiday'].includes(other.type)) {
        if (yearlyOrHolidayDateRangesOverlap(schedule, other)) {
          if (timeRangesOverlap(
            thisTimeRange.start, thisTimeRange.end,
            otherTimeRange.start, otherTimeRange.end
          )) {
            conflicts.push({
              schedule: other,
              thisTime: thisTimeRange,
              otherTime: otherTimeRange,
              note: 'Yearly/holiday schedules overlap on same calendar dates'
            });
          }
        }
      }
      
      // Mixed types - check if they could potentially overlap
      else if ((schedule.type === 'weekly' && other.type === 'daily') || 
               (schedule.type === 'daily' && other.type === 'weekly')) {
        // Simplified check - if time ranges overlap, flag it
        if (timeRangesOverlap(
          thisTimeRange.start, thisTimeRange.end,
          otherTimeRange.start, otherTimeRange.end
        )) {
          conflicts.push({
            schedule: other,
            thisTime: thisTimeRange,
            otherTime: otherTimeRange,
            note: 'Different schedule types may overlap'
          });
        }
      }
      
      // Any other mixed type combination — simplified date range + time range check
      else {
        const thisStart = schedule.start_date ? new Date(schedule.start_date) : new Date(0);
        const thisEnd = schedule.end_date ? new Date(schedule.end_date) : new Date('2099-12-31');
        const otherStart = other.start_date ? new Date(other.start_date) : new Date(0);
        const otherEnd = other.end_date ? new Date(other.end_date) : new Date('2099-12-31');
        
        if (thisStart <= otherEnd && otherStart <= thisEnd) {
          if (timeRangesOverlap(
            thisTimeRange.start, thisTimeRange.end,
            otherTimeRange.start, otherTimeRange.end
          )) {
            conflicts.push({
              schedule: other,
              thisTime: thisTimeRange,
              otherTime: otherTimeRange,
              note: 'Different schedule types may overlap'
            });
          }
        }
      }
    });
    
    return conflicts;
  };

  // Distinct conflicting schedule PAIRS, for the System health tile. Conflict
  // detection lives here rather than in the backend, so the health endpoint
  // takes this as an input instead of guessing. Counting pairs (not per-schedule

  // Analyze ALL schedule conflicts across the entire configuration
  // Returns structured conflict objects with suggested auto-resolutions
  const analyzeAllConflicts = (lookaheadDays = 30, startDate = null) => {
    const allConflicts = [];
    const seen = new Set(); // Avoid duplicate pairs
    const activeSchedules = schedules.filter(s => s.is_active);

    const normalizeDay = (dateStr) => {
      if (!dateStr) return null;
      const d = new Date(dateStr);
      return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
    };

    const rangeStart = startDate ? new Date(startDate) : new Date();
    const today = new Date(rangeStart.getFullYear(), rangeStart.getMonth(), rangeStart.getDate());

    // Group-aware results ensure a pair is actionable only when it reaches
    // winner selection after exclusive and blend semantics are applied.
    const actionableConflictDaysByPair = buildActionableConflictDaysByPair(
      activeSchedules,
      lookaheadDays,
      today
    );

    // Check all pairs of active schedules
    for (let i = 0; i < activeSchedules.length; i++) {
      for (let j = i + 1; j < activeSchedules.length; j++) {
        const a = activeSchedules[i];
        const b = activeSchedules[j];
        const pairKey = getSchedulePairKey(a, b);
        if (seen.has(pairKey)) continue;

        // Parse recurrence patterns
        let patternA = {}, patternB = {};
        try { patternA = a.recurrence_pattern ? JSON.parse(a.recurrence_pattern) : {}; } catch (e) { patternA = {}; }
        try { patternB = b.recurrence_pattern ? JSON.parse(b.recurrence_pattern) : {}; } catch (e) { patternB = {}; }

        const priorityA = a.priority ?? 5;
        const priorityB = b.priority ?? 5;
        const timeA = patternA.timeRange || {};
        const timeB = patternB.timeRange || {};

        // Find overlapping concrete occurrences. Overnight windows belong to
        // their start day, so adjacent recurrence anchors must be compared too.
        const overlappingDayTimes = new Set();
        for (let aDayOffset = -1; aDayOffset < lookaheadDays; aDayOffset += 1) {
          const anchorA = new Date(today.getFullYear(), today.getMonth(), today.getDate() + aDayOffset);
          if (!isScheduleActiveOnDay(a, anchorA.getTime(), normalizeDay)) continue;

          for (const relativeAnchorOffset of [-1, 0, 1]) {
            const bDayOffset = aDayOffset + relativeAnchorOffset;
            if (bDayOffset < -1 || bDayOffset > lookaheadDays) continue;

            const anchorB = new Date(today.getFullYear(), today.getMonth(), today.getDate() + bDayOffset);
            if (!isScheduleActiveOnDay(b, anchorB.getTime(), normalizeDay)) continue;

            const overlap = getAnchoredTimeRangeOverlap(
              timeA.start,
              timeA.end,
              0,
              timeB.start,
              timeB.end,
              relativeAnchorOffset
            );
            if (!overlap) continue;

            const overlapDayOffset = aDayOffset + Math.floor(overlap.start / (24 * 60));
            if (overlapDayOffset >= 0 && overlapDayOffset < lookaheadDays) {
              const overlapDay = new Date(
                today.getFullYear(),
                today.getMonth(),
                today.getDate() + overlapDayOffset
              );
              overlappingDayTimes.add(overlapDay.getTime());
            }
          }
        }

        const overlappingDays = [...overlappingDayTimes]
          .sort((first, second) => first - second)
          .map(dayTime => new Date(dayTime));

        if (overlappingDays.length === 0) continue;
        const actionableOverlappingDays = actionableConflictDaysByPair.get(pairKey) || [];

        // Both exclusive, same priority = ambiguous-priority conflict (HIGH severity)
        if (
          a.exclusive
          && b.exclusive
          && priorityA === priorityB
          && actionableOverlappingDays.length > 0
        ) {
          seen.add(pairKey);
          const categoryA = categories.find(c => c.id === a.category_id);
          const categoryB = categories.find(c => c.id === b.category_id);
          
          const suggestions = [];
          // Suggestion 1: Raise A's priority
          if (priorityA < 10) {
            suggestions.push({
              id: `${pairKey}-raise-a`,
              label: `Raise "${a.name}" priority to ${priorityA + 1} (makes it always win)`,
              icon: 'crown',
              changes: [{ scheduleId: a.id, field: 'priority', value: priorityA + 1 }]
            });
          }
          // Suggestion 2: Raise B's priority
          if (priorityB < 10) {
            suggestions.push({
              id: `${pairKey}-raise-b`,
              label: `Raise "${b.name}" priority to ${priorityB + 1} (makes it always win)`,
              icon: 'crown',
              changes: [{ scheduleId: b.id, field: 'priority', value: priorityB + 1 }]
            });
          }
          // Exclusive schedules suppress all blending. To make both play, both
          // schedules must become non-exclusive and have blending enabled.
          suggestions.push({
            id: `${pairKey}-blend-both`,
            label: 'Make both schedules non-exclusive and enable blending on both',
            icon: 'shuffle',
            changes: buildBlendBothChanges(a, b)
          });
          // Suggestion 4: Split time ranges (only if both are daily/weekly with time support)
          if ((a.type === 'daily' || a.type === 'weekly') && (b.type === 'daily' || b.type === 'weekly')) {
            suggestions.push({
              id: `${pairKey}-split-time`,
              label: `Split time ranges: "${a.name}" 12AM-11:59AM, "${b.name}" 12PM-11:59PM`,
              icon: 'clock',
              changes: [
                { scheduleId: a.id, field: 'timeRange', value: { start: '00:00', end: '11:59' } },
                { scheduleId: b.id, field: 'timeRange', value: { start: '12:00', end: '23:59' } }
              ]
            });
          }

          allConflicts.push({
            id: pairKey,
            type: 'same-priority-exclusive',
            severity: 'high',
            scheduleA: a,
            scheduleB: b,
            categoryA: categoryA?.name || 'Unknown',
            categoryB: categoryB?.name || 'Unknown',
            overlappingDays: actionableOverlappingDays,
            description: `Both schedules are exclusive with priority ${priorityA}. NeXroll's fixed tie-break order selects one during overlap, so the intended winner is not explicit.`,
            suggestions
          });
        }
        // Both exclusive, different priority = one always overrides the other (deterministic, not a conflict)
        else if (a.exclusive && b.exclusive && priorityA !== priorityB) {
          const winner = priorityA > priorityB ? a : b;
          const loser = priorityA > priorityB ? b : a;
          const loserPriority = priorityA > priorityB ? priorityB : priorityA;
          const winnerPriority = priorityA > priorityB ? priorityA : priorityB;
          const categoryLoser = categories.find(c => c.id === loser.category_id);

          seen.add(pairKey);
          const suggestions = [];
          // An exclusive winner suppresses blending entirely. Both schedules
          // must opt out of exclusivity before a blended result is possible.
          suggestions.push({
            id: `${pairKey}-blend-both`,
            label: 'Make both schedules non-exclusive and enable blending on both',
            icon: 'shuffle',
            changes: buildBlendBothChanges(winner, loser)
          });
          // Suggestion: Raise loser priority above winner
          if (winnerPriority < 10) {
            suggestions.push({
              id: `${pairKey}-raise-loser`,
              label: `Raise "${loser.name}" priority to ${winnerPriority + 1} (makes it win instead)`,
              icon: 'crown',
              changes: [{ scheduleId: loser.id, field: 'priority', value: winnerPriority + 1 }]
            });
          }
          // Suggestion: Disable the overridden schedule
          suggestions.push({
            id: `${pairKey}-disable-loser`,
            label: `Disable "${loser.name}" during overlap period (it never plays anyway)`,
            icon: 'ban',
            changes: [{ scheduleId: loser.id, field: 'is_active', value: false }]
          });

          allConflicts.push({
            id: pairKey,
            type: 'exclusive-override',
            severity: 'info',
            scheduleA: winner,
            scheduleB: loser,
            categoryA: categories.find(c => c.id === winner.category_id)?.name || 'Unknown',
            categoryB: categoryLoser?.name || 'Unknown',
            overlappingDays,
            description: `"${winner.name}" (priority ${winnerPriority}) always overrides "${loser.name}" (priority ${loserPriority}). The lower-priority schedule never plays during overlap.`,
            suggestions
          });
        }
        // One exclusive, one non-exclusive = exclusive overrides
        else if ((a.exclusive && !b.exclusive) || (!a.exclusive && b.exclusive)) {
          const exclusive = a.exclusive ? a : b;
          const nonExclusive = a.exclusive ? b : a;
          const exclusivePriority = exclusive.priority ?? 5;
          const nonExclusivePriority = nonExclusive.priority ?? 5;

          // The backend evaluates exclusivity before priority, so every such
          // overlap must be reported, even when the non-exclusive priority is higher.
          {
            seen.add(pairKey);
            const categoryNonExcl = categories.find(c => c.id === nonExclusive.category_id);
            const suggestions = [];
            suggestions.push({
              id: `${pairKey}-blend-both`,
              label: 'Make both schedules non-exclusive and enable blending on both',
              icon: 'shuffle',
              changes: buildBlendBothChanges(exclusive, nonExclusive)
            });
            const winningPriority = priorityToBeatExclusive(exclusivePriority, nonExclusivePriority);
            if (winningPriority !== null) {
              suggestions.push({
                id: `${pairKey}-raise-non-excl`,
                label: `Make "${nonExclusive.name}" exclusive with priority ${winningPriority} (makes it win)`,
                icon: 'lock',
                changes: [
                  { scheduleId: nonExclusive.id, field: 'exclusive', value: true },
                  { scheduleId: nonExclusive.id, field: 'priority', value: winningPriority }
                ]
              });
            }

            allConflicts.push({
              id: pairKey,
              type: 'exclusive-blocks-nonexclusive',
              severity: 'info',
              scheduleA: exclusive,
              scheduleB: nonExclusive,
              categoryA: categories.find(c => c.id === exclusive.category_id)?.name || 'Unknown',
              categoryB: categoryNonExcl?.name || 'Unknown',
              overlappingDays,
              description: `"${exclusive.name}" is exclusive and blocks "${nonExclusive.name}" from playing during overlap. This is by design — exclusive schedules always take priority.`,
              suggestions
            });
          }
        }
        // A lone blend flag falls back to normal selection; the pair only
        // coexists intentionally when both schedules opt into blending.
        else if (
          !a.exclusive
          && !b.exclusive
          && priorityA === priorityB
          && !isEffectiveBlendPair(a, b)
          && actionableOverlappingDays.length > 0
        ) {
          seen.add(pairKey);
          const categoryA = categories.find(c => c.id === a.category_id);
          const categoryB = categories.find(c => c.id === b.category_id);

          const suggestions = [];
          // Suggestion 1: Raise A's priority
          if (priorityA < 10) {
            suggestions.push({
              id: `${pairKey}-raise-a`,
              label: `Raise "${a.name}" priority to ${priorityA + 1} (makes it always win)`,
              icon: 'crown',
              changes: [{ scheduleId: a.id, field: 'priority', value: priorityA + 1 }]
            });
          }
          // Suggestion 2: Raise B's priority
          if (priorityB < 10) {
            suggestions.push({
              id: `${pairKey}-raise-b`,
              label: `Raise "${b.name}" priority to ${priorityB + 1} (makes it always win)`,
              icon: 'crown',
              changes: [{ scheduleId: b.id, field: 'priority', value: priorityB + 1 }]
            });
          }
          // Suggestion 3: Enable blend on both
          suggestions.push({
            id: `${pairKey}-blend-both`,
            label: `Enable blending on both (prerolls from both schedules play together)`,
            icon: 'shuffle',
            changes: [
              { scheduleId: a.id, field: 'blend_enabled', value: true },
              { scheduleId: b.id, field: 'blend_enabled', value: true }
            ]
          });

          allConflicts.push({
            id: pairKey,
            type: 'same-priority-nonexclusive',
            severity: 'high',
            scheduleA: a,
            scheduleB: b,
            categoryA: categoryA?.name || 'Unknown',
            categoryB: categoryB?.name || 'Unknown',
            overlappingDays: actionableOverlappingDays,
            description: `Both schedules have priority ${priorityA}, but fewer than two schedules are blending. NeXroll's fixed tie-break order selects one, so the intended winner is not explicit.`,
            suggestions
          });
        }
      }
    }

    // Sort: high severity first, then info
    const severityOrder = { high: 0, medium: 1, low: 2, info: 3 };
    allConflicts.sort((a, b) => severityOrder[a.severity] - severityOrder[b.severity]);
    return allConflicts;
  };

  // Apply a single conflict resolution fix
  // Every conflict count on the dashboard comes from here, and this is exactly
  // what the Conflicts page lists. Anything counted can therefore be opened and
  // acted on, which was not true when the tiles ran their own detector over a
  // different time window.
  const actionableConflicts = React.useMemo(() => {
    try {
      const ignoredSet = new Set(ignoredConflicts || []);
      // 'info' rows describe a deterministic outcome -- one schedule always
      // wins -- and the Conflicts page counts them separately for that reason.
      // Counting them as conflicts told people seven things needed attention
      // when one did.
      return (analyzeAllConflicts(30) || [])
        .filter(conflict => !ignoredSet.has(conflict.id) && conflict.severity !== 'info');
    } catch {
      return null;
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [schedules, categories, ignoredConflicts]);

  // Pairs, for the health tile.
  const dashboardConflictCount = actionableConflicts ? actionableConflicts.length : null;

  // Keep live connection health current even when schedule/library inputs stay unchanged.
  const healthSummary = useHealthSummary(
    apiUrl(`system/health/summary${dashboardConflictCount == null ? '' : `?conflicts=${dashboardConflictCount}`}`),
    schedulerStatus.running, prerolls.length, activeCategory
  );

  // The conflicts one saved schedule is caught in, taken from the same list the
  // Conflicts page renders. getScheduleConflicts stays for drafts: a schedule
  // being typed into the form is not saved yet, so it still needs detection run
  // against it directly.
  const conflictsForSchedule = (schedule) => {
    if (!schedule?.id) return [];
    return (actionableConflicts || []).filter(conflict => (
      conflict?.scheduleA?.id === schedule.id || conflict?.scheduleB?.id === schedule.id
    ));
  };

  const conflictingScheduleIds = React.useMemo(() => {
    const ids = new Set();
    (actionableConflicts || []).forEach(conflict => {
      if (conflict?.scheduleA?.id != null) ids.add(conflict.scheduleA.id);
      if (conflict?.scheduleB?.id != null) ids.add(conflict.scheduleB.id);
    });
    return ids;
  }, [actionableConflicts]);

  const applyConflictFix = async (changes, workingSchedules) => {
    const results = [];
    // Group changes by scheduleId
    const bySchedule = {};
    for (const change of changes) {
      if (!bySchedule[change.scheduleId]) bySchedule[change.scheduleId] = [];
      bySchedule[change.scheduleId].push(change);
    }

    for (const [schedId, schedChanges] of Object.entries(bySchedule)) {
      const numericScheduleId = parseInt(schedId, 10);
      const sched = workingSchedules.get(numericScheduleId);
      if (!sched) { results.push({ schedId, success: false, error: 'Schedule not found' }); continue; }

      // Build the update payload from existing schedule data
      let pattern = {};
      try { pattern = sched.recurrence_pattern ? JSON.parse(sched.recurrence_pattern) : {}; } catch (e) { pattern = {}; }

      const payload = {
        name: sched.name,
        type: sched.type,
        start_date: sched.start_date,
        end_date: sched.end_date || null,
        category_id: sched.category_id,
        playlist: sched.playlist,
        recurrence_pattern: sched.recurrence_pattern || null,
        preroll_ids: sched.preroll_ids || null,
        fallback_category_id: sched.fallback_category_id || null,
        sequence: sched.sequence || null,
        color: sched.color || null,
        is_active: sched.is_active,
        blend_enabled: sched.blend_enabled,
        priority: sched.priority ?? 5,
        exclusive: sched.exclusive ?? false,
        holiday_name: sched.holiday_name || null,
        holiday_country: sched.holiday_country || null,
        source_sequence_id: sched.source_sequence_id ?? null
      };

      // Apply each change
      for (const change of schedChanges) {
        if (change.field === 'timeRange') {
          // Merge time range into recurrence pattern
          pattern.timeRange = change.value;
          payload.recurrence_pattern = JSON.stringify(pattern);
        } else {
          payload[change.field] = change.value;
        }
      }

      try {
        const res = await fetch(apiUrl(`schedules/${schedId}`), {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        // Use successful updates as the baseline for later fixes that touch the
        // same schedule, instead of rebuilding from stale React state.
        workingSchedules.set(numericScheduleId, { ...sched, ...payload });
        results.push({ schedId, success: true });
      } catch (err) {
        results.push({ schedId, success: false, error: err.message });
      }
    }
    return results;
  };

  // Apply all selected conflict resolutions
  const applyAllConflictResolutions = async (allConflicts) => {
    setConflictWizardApplying(true);
    const applied = [];
    const failed = [];
    const workingSchedules = new Map(schedules.map(schedule => [schedule.id, { ...schedule }]));

    for (const conflict of allConflicts) {
      const selectedFixId = conflictResolutions[conflict.id];
      if (!selectedFixId) continue;
      const fix = conflict.suggestions.find(s => s.id === selectedFixId);
      if (!fix) continue;

      const results = await applyConflictFix(fix.changes, workingSchedules);
      const allOk = results.every(r => r.success);
      if (allOk) {
        applied.push({ conflict, fix });
      } else {
        failed.push({ conflict, fix, errors: results.filter(r => !r.success) });
      }
    }

    setConflictWizardApplying(false);
    setConflictWizardResults({ applied, failed });
    fetchData(); // Refresh schedule data
  };

  // Apply one fix for one conflict immediately (used by the Command Center conflicts page)
  const applySingleConflictFix = async (conflict, fix) => {
    if (!fix) return;
    setConflictWizardApplying(true);
    const workingSchedules = new Map(schedules.map(schedule => [schedule.id, { ...schedule }]));
    const results = await applyConflictFix(fix.changes, workingSchedules);
    setConflictWizardApplying(false);
    setShowConflictAlternatives(false);
    if (results.every(r => r.success)) {
      showAlert(`Applied: ${fix.label}`, 'success');
      setConflictResolutions(values => ({ ...values, [conflict.id]: fix.id }));
      fetchData();
    } else {
      showAlert('Could not apply that fix. Try editing the schedules manually.', 'error');
    }
  };

  // Auto-resolve: pick the best suggestion for each conflict
  const autoResolveConflicts = (allConflicts) => {
    const auto = {};
    for (const conflict of allConflicts) {
      if (conflict.suggestions.length > 0) {
        // For same-priority: prefer raising the first schedule's priority
        // For overrides: prefer enabling blend on the loser
        // For exclusive-blocks: prefer enabling blend
        auto[conflict.id] = conflict.suggestions[0].id;
      }
    }
    setConflictResolutions(auto);
  };

  // Load ignored conflicts from backend
  // Load once at startup. Without this the list stays empty until the conflicts
  // tab is opened, which is why ignored conflicts reappeared after a reload and
  // the counts on the dashboard disagreed with the ones behind the button.
  React.useEffect(() => {
    let cancelled = false;
    fetch(apiUrl('conflicts/ignored'))
      .then(res => (res.ok ? res.json() : null))
      .then(data => { if (!cancelled && data) setIgnoredConflicts(data.ignored || []); })
      .catch(() => {});
    return () => { cancelled = true; };
  }, []);

  const loadIgnoredConflicts = async () => {
    try {
      const res = await fetch(apiUrl('conflicts/ignored'));
      if (res.ok) {
        const data = await res.json();
        setIgnoredConflicts(data.ignored || []);
      }
    } catch (e) { /* silent */ }
  };

  // Ignore a conflict pair
  const ignoreConflict = async (pairKey) => {
    try {
      const res = await fetch(apiUrl('conflicts/ignore'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ pair_key: pairKey })
      });
      if (res.ok) {
        const data = await res.json();
        setIgnoredConflicts(data.ignored || []);
        // Remove any selected resolution for this conflict
        setConflictResolutions(prev => {
          const next = { ...prev };
          delete next[pairKey];
          return next;
        });
        showAlert('Conflict ignored — hidden from future scans', 'success');
      } else {
        const errData = await safeJson(res);
        showAlert(errData?.detail || 'Failed to ignore conflict', 'error');
      }
    } catch (e) {
      console.error('ignoreConflict error:', e);
      showAlert('Failed to ignore conflict', 'error');
    }
  };

  // Un-ignore a conflict pair
  const unignoreConflict = async (pairKey) => {
    try {
      const res = await fetch(apiUrl(`conflicts/ignore/${pairKey}`), { method: 'DELETE' });
      if (res.ok) {
        const data = await res.json();
        setIgnoredConflicts(data.ignored || []);
        showAlert('Conflict restored — will appear in future scans', 'success');
      } else {
        const errData = await safeJson(res);
        showAlert(errData?.detail || 'Failed to restore conflict', 'error');
      }
    } catch (e) {
      console.error('unignoreConflict error:', e);
      showAlert('Failed to restore conflict', 'error');
    }
  };

  // Bulk selection handlers
  // System categories can't be deleted, which is all a selection is for, so
  // they can't be selected either.
  const toggleSelectCategory = (categoryId) => {
    if (categories.some(c => c.id === categoryId && c.is_system)) return;
    setSelectedCategoryIds(prev =>
      prev.includes(categoryId)
        ? prev.filter(id => id !== categoryId)
        : [...prev, categoryId]
    );
  };

  const toggleSelectAll = () => {
    const filteredIds = getFilteredCategories().filter(c => !c.is_system).map(c => c.id);
    if (filteredIds.length > 0 && filteredIds.every(id => selectedCategoryIds.includes(id))) {
      setSelectedCategoryIds([]);
    } else {
      setSelectedCategoryIds(filteredIds);
    }
  };

  const handleBulkDelete = async () => {
    if (selectedCategoryIds.length === 0) {
      alert('No categories selected');
      return;
    }
    
    const confirmMsg = `Delete ${selectedCategoryIds.length} selected categories?\n\nThis will also remove all associated schedules and preroll assignments.`;
    if (!await showConfirm(confirmMsg, { title: 'Delete Categories', type: 'danger', confirmText: 'Delete' })) return;
    
    // fetch() doesn't throw on a refusal (a system category answers 403), so
    // count the responses rather than reporting every request as a deletion.
    const results = await Promise.all(
      selectedCategoryIds.map(id =>
        fetch(apiUrl(`categories/${id}`), { method: 'DELETE' }).then(res => res.ok).catch(() => false)
      )
    );
    const deleted = results.filter(Boolean).length;
    const failed = results.length - deleted;
    showAlert(failed
      ? `Deleted ${deleted} categor${deleted === 1 ? 'y' : 'ies'}; ${failed} could not be deleted`
      : `Deleted ${deleted} categor${deleted === 1 ? 'y' : 'ies'}`, failed ? 'error' : 'success');
    setSelectedCategoryIds([]);
    setBulkActionMode(false);
    fetchData();
  };

  // Get filtered categories based on active filter
  const getFilteredCategories = () => {
    let filtered = categories;
    
    // Apply category filter
    switch (categoryFilter) {
      case 'active':
        filtered = filtered.filter(c => getCategoryStats(c).hasActiveSchedules);
        break;
      case 'hasPrerolls':
        filtered = filtered.filter(c => {
          const stats = getCategoryStats(c);
          return stats.totalPrerolls > 0;
        });
        break;
      case 'empty':
        filtered = filtered.filter(c => {
          const stats = getCategoryStats(c);
          return stats.totalPrerolls === 0;
        });
        break;
      case 'system':
        filtered = filtered.filter(c => c.is_system);
        break;
      default: // 'all'
        break;
    }
    
    // Apply search query
    if (categorySearchQuery) {
      const query = categorySearchQuery.toLowerCase();
      filtered = filtered.filter(c => 
        c.name.toLowerCase().includes(query) || 
        (c.description && c.description.toLowerCase().includes(query))
      );
    }
    
    return filtered;
  };

  // Categories in the order the sort menu asks for, with their stats. The grid
  // used to ignore the sort; both views use this now.
  const sortCategoryList = (list) => {
    const direction = categorySortDirection === 'desc' ? -1 : 1;
    const byName = (a, b) => a.category.name.localeCompare(b.category.name, undefined, { sensitivity: 'base' });
    return list
      .map(category => ({ category, stats: getCategoryStats(category) }))
      .sort((a, b) => {
        if (categorySortField === 'prerolls') return (a.stats.totalPrerolls - b.stats.totalPrerolls) * direction || byName(a, b);
        if (categorySortField === 'status') return (a.stats.activeSchedules - b.stats.activeSchedules) * direction || byName(a, b);
        return byName(a, b) * direction;
      });
  };

  // The library, filtered to one category. NeX-Up's own items show there even
  // while they're hidden from the rest of the library.
  const viewCategoryInLibrary = (category) => {
    setFilterCategory(String(category.id));
    setFilterMatchStatus('');
    setCurrentPage(1);
    setActiveTab('library');
  };

  // Format duration helper
  const formatDuration = (seconds) => {
    if (!seconds) return '0s';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    if (mins > 0) {
      return `${mins}m ${secs}s`;
    }
    return `${secs}s`;
  };

  const toggleScheduler = () => {
    const action = schedulerStatus.running ? 'stop' : 'start';
    fetch(apiUrl(`scheduler/${action}`), { method: 'POST' })
      .then(res => res.json())
      .then(data => {
        alert(`Scheduler ${action}ed!`);
        fetchData();
      });
  };

  const resetBackupProgress = () => setBackupProgress({ active: false, type: '', message: '', percent: null, loaded: 0, total: 0 });

  // Stream a download so we can show real byte progress. Returns the assembled
  // Blob. `total` comes from X-Estimated-Total (backups compress on the fly so
  // there's no exact Content-Length) or Content-Length, else indeterminate.
  const downloadWithProgress = async (url, opts, type, label) => {
    const res = await fetch(url, opts);
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try { detail = (await res.json()).detail || detail; } catch (_) {}
      throw new Error(detail);
    }
    const cd = res.headers.get('content-disposition');
    let filename = null;
    if (cd) { const m = cd.match(/filename="?([^"]+)"?/); if (m) filename = m[1]; }
    const total = Number(res.headers.get('x-estimated-total') || res.headers.get('content-length') || 0);
    if (!res.body || !res.body.getReader) {
      // Streaming unsupported — fall back to a plain blob.
      return { blob: await res.blob(), filename };
    }
    const reader = res.body.getReader();
    const chunks = [];
    let loaded = 0;
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value);
      loaded += value.length;
      const percent = total > 0 ? Math.min(99, Math.round((loaded / total) * 100)) : null;
      setBackupProgress({ active: true, type, message: label, percent, loaded, total });
    }
    return { blob: new Blob(chunks), filename };
  };

