  const handleRescanPrerolls = async ({ deleteMissing = false, dedupe = false, confirmText = null } = {}) => {
    if (deleteMissing) {
      const ok = window.confirm(
        confirmText || 'Remove database rows for prerolls whose files are missing from disk? This cannot be undone.'
      );
      if (!ok) return;
    }
    if (dedupe) {
      const ok = window.confirm(
        'Merge duplicate database rows that point at the same file? Tags will be carried over to the kept row.'
      );
      if (!ok) return;
    }
    const message = deleteMissing
      ? 'Scanning and removing missing files...'
      : dedupe
        ? 'Scanning and deduping rows...'
        : 'Scanning preroll folder...';
    setBackupProgress({ active: true, type: 'rescan', message });
    try {
      const qs = new URLSearchParams();
      if (deleteMissing) qs.set('delete_missing', 'true');
      if (dedupe) qs.set('dedupe', 'true');
      const url = qs.toString() ? `prerolls/rescan?${qs.toString()}` : 'prerolls/rescan';
      const res = await fetch(apiUrl(url), { method: 'POST' });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.detail || `HTTP ${res.status}: Rescan failed`);
      }
      const stats = await res.json();
      setBackupProgress({ active: false, type: '', message: '' });
      const lines = [
        `Scanned ${stats.files_on_disk || 0} files on disk.`,
        `${stats.paths_updated || 0} path${stats.paths_updated === 1 ? '' : 's'} relinked.`,
        `${stats.thumbnails_generated || 0} thumbnail${stats.thumbnails_generated === 1 ? '' : 's'} generated.`,
        `${stats.new_prerolls || 0} new file${stats.new_prerolls === 1 ? '' : 's'} added.`,
        `${stats.missing_files || 0} file${stats.missing_files === 1 ? '' : 's'} still missing.`,
      ];
      if (deleteMissing) {
        lines.push(`${stats.deleted_missing || 0} missing row${stats.deleted_missing === 1 ? '' : 's'} removed.`);
      } else if (stats.deleted_missing) {
        // The ordinary scan clears entries for files deleted from folders that are still there.
        lines.push(`${stats.deleted_missing} entr${stats.deleted_missing === 1 ? 'y' : 'ies'} for deleted files removed.`);
      }
      if (!deleteMissing && stats.storage_maybe_offline && stats.missing_not_pruned) {
        lines.push(`The missing files were in folders that are gone or empty, so NeXroll kept their entries in case the storage is offline. If you deleted them, remove them with Remove Missing Rows in Settings > Backup & Restore.`);
      }
      if (dedupe) {
        lines.push(`${stats.deduped_rows || 0} duplicate row${stats.deduped_rows === 1 ? '' : 's'} merged.`);
      }
      showAlert(lines.join(' '), 'success');
      fetchData();
      fetchStorageHealth();
    } catch (error) {
      console.error('Rescan error:', error);
      setBackupProgress({ active: false, type: '', message: '' });
      showAlert('Rescan failed: ' + error.message, 'error');
    }
  };

