  const handleDeleteCategory = async (categoryId) => {
    // First, fetch the deletion impact so we can show the user exactly what will happen.
    let impact = null;
    try {
      const impRes = await fetch(apiUrl(`categories/${categoryId}/delete-impact`));
      if (impRes.ok) {
        impact = await impRes.json();
      }
    } catch (e) {
      // Non-fatal — fall back to a generic confirmation if the impact endpoint is unavailable
    }

    let confirmMsg;
    if (impact) {
      const prerollN = impact.preroll_count || 0;
      const uncatN = impact.becoming_uncategorized || 0;
      const schedN = impact.schedule_count || 0;
      const fallbackN = impact.schedule_fallback_count || 0;
      const holidayN = impact.holiday_preset_count || 0;
      const lines = [`Delete category "${impact.category_name}"?`, ''];
      if (prerollN === 0 && schedN === 0 && fallbackN === 0 && holidayN === 0) {
        lines.push('This category is empty. Nothing else will be affected.');
      } else {
        lines.push('This will:');
        if (prerollN > 0) {
          lines.push(` • Remove this category from ${prerollN} preroll${prerollN === 1 ? '' : 's'}`);
          if (uncatN > 0) lines.push(`     (${uncatN} of those will become uncategorized — this is their only category)`);
        }
        if (schedN > 0)   lines.push(` • Disable ${schedN} schedule${schedN === 1 ? '' : 's'} that target this category (they will need a new category before re-enabling)`);
        if (fallbackN > 0)lines.push(` • Clear this category from ${fallbackN} schedule fallback${fallbackN === 1 ? '' : 's'}`);
        if (holidayN > 0) lines.push(` • Delete ${holidayN} holiday preset${holidayN === 1 ? '' : 's'} that reference this category`);
        lines.push('');
        lines.push('Preroll video files on disk will NOT be deleted.');
      }
      confirmMsg = lines.join('\n');
    } else {
      confirmMsg = 'Are you sure you want to delete this category? Affected prerolls will lose this category tag and affected schedules will be disabled.';
    }

    if (!await showConfirm(confirmMsg, { type: 'danger', title: 'Delete Category' })) return;

    try {
      const res = await fetch(apiUrl(`categories/${categoryId}`), { method: 'DELETE' });
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        throw new Error(errData.detail || `HTTP error! status: ${res.status}`);
      }
      const result = await res.json().catch(() => ({}));
      const removed = result.removed_m2m || 0;
      const disabled = result.disabled_schedules || 0;
      let msg = 'Category deleted successfully!';
      if (removed > 0 || disabled > 0) {
        const parts = [];
        if (removed > 0) parts.push(`removed tag from ${removed} preroll${removed === 1 ? '' : 's'}`);
        if (disabled > 0) parts.push(`${disabled} schedule${disabled === 1 ? '' : 's'} disabled`);
        msg += `\n${parts.join(', ')}.`;
      }
      alert(msg);
      fetchData();
    } catch (error) {
      console.error('Delete category error:', error);
      alert(error.message || 'Failed to delete category');
    }
  };

  const handleEditCategory = (category) => {
    if (!category || category.is_system) return;
    setEditingCategory(category);
    setNewCategory({ name: category.name, description: category.description || '' });
    try { loadCategoryPrerolls(category.id); } catch (e) {}
  };

  const handleUpdateCategory = async (e) => {
    e.preventDefault();
    if (!editingCategory) return;

    const name = (newCategory.name || '').trim();
    const description = (newCategory.description || '').trim();
    if (!name) {
      alert('Category name is required');
      return;
    }

    try {
      const res = await fetch(apiUrl(`categories/${editingCategory.id}`), {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, description })
      });
      const text = await res.text();
      let data = null;
      try { data = text ? JSON.parse(text) : null; } catch {}

      if (!res.ok) {
        const msg = (data && (data.detail || data.message)) || text || `HTTP ${res.status}`;
        throw new Error(msg);
      }

      showAlert(`Saved "${name}"`, 'success');
      setEditingCategory(null);
      setNewCategory({ name: '', description: '' });
      setCategoryAddSelectedIds([]);
      setCategoryAddSearch('');
      setCategoryAddFolder('');

      if (data && data.id) {
        setCategories(prev => prev.map(c => c.id === data.id ? data : c));
      } else {
        fetchData();
      }
    } catch (error) {
      console.error('Update category error:', error);
      alert(error.message.includes('already exists') ? 'Category name already exists' : 'Failed to update category: ' + error.message);
    }
  };

  // Category preroll management helpers

  const loadCategoryPrerolls = async (categoryId) => {
    setCategoryPrerollsLoading(prev => ({ ...prev, [categoryId]: true }));
    try {
      const res = await fetch(apiUrl(`categories/${categoryId}/prerolls`));
      const data = await safeJson(res);
      setCategoryPrerolls(prev => ({ ...prev, [categoryId]: Array.isArray(data) ? data : [] }));
    } catch (e) {
      console.error('Load category prerolls error:', e);
      setCategoryPrerolls(prev => ({ ...prev, [categoryId]: [] }));
    } finally {
      setCategoryPrerollsLoading(prev => ({ ...prev, [categoryId]: false }));
    }
  };


  const handleCategoryRemovePreroll = async (categoryId, preroll) => {
    if (!preroll) return;
    if (!await showConfirm(`Remove "${preroll.display_name || preroll.filename}" from this category?`, { type: 'warning', title: 'Remove from Category' })) return;
    try {
      const res = await fetch(apiUrl(`categories/${categoryId}/prerolls/${preroll.id}`), { method: 'DELETE' });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(text || `HTTP ${res.status}`);
      }
      setCategoryPrerolls(prev => ({
        ...prev,
        [categoryId]: (prev[categoryId] || []).filter(p => p.id !== preroll.id)
      }));
      fetchData();
    } catch (e) {
      console.error('Remove preroll from category error:', e);
      alert('Failed to remove preroll from category: ' + e.message);
    }
  };

  const handleCategoryAddPreroll = async (categoryId, prerollIds = null) => {
    const sel = categoryAddSelection[categoryId] || {};
    const idsToAdd = prerollIds || (categoryAddSelectedIds.length > 0 ? categoryAddSelectedIds : (sel.prerollId ? [sel.prerollId] : []));
    if (!idsToAdd || idsToAdd.length === 0) {
      alert('Please select at least one preroll to add');
      return;
    }
    // v1.13.13: categories are flat tags; never send set_primary. Adding a preroll to a
    // category just attaches the tag — does not move files on disk.
    let successCount = 0;
    let failCount = 0;
    try {
      for (const prerollId of idsToAdd) {
        try {
          const res = await fetch(apiUrl(`categories/${categoryId}/prerolls/${prerollId}`), { method: 'POST' });
          if (res.ok) {
            successCount++;
          } else {
            failCount++;
          }
        } catch {
          failCount++;
        }
      }
      setCategoryAddSelection(prev => ({ ...prev, [categoryId]: { prerollId: '' } }));
      setCategoryAddSelectedIds([]);
      setCategoryAddSearch('');
      setCategoryAddFolder('');
      loadCategoryPrerolls(categoryId);
      fetchData();
      if (failCount === 0) {
        showAlert(`Added ${successCount} preroll${successCount !== 1 ? 's' : ''} to this category`, 'success');
      } else {
        showAlert(`Added ${successCount}; ${failCount} failed`, 'error');
      }
    } catch (e) {
      console.error('Add preroll to category error:', e);
      alert('Failed to add prerolls to category: ' + e.message);
    }
  };

  const availablePrerollsForCategory = (categoryId) => {
    const assigned = new Set((categoryPrerolls[categoryId] || []).map(p => p.id));
    return prerolls.filter(p => !assigned.has(p.id));
  };

  // UI helpers and derived values for prerolls list
  const formatBytes = (bytes) => {
    const b = Number(bytes) || 0;
    if (b <= 0) return '0 B';
    const units = ['B','KB','MB','GB','TB','PB'];
    const i = Math.floor(Math.log(b) / Math.log(1024));
    const val = b / Math.pow(1024, i);
    const prec = i === 0 ? 0 : (val >= 100 ? 0 : val >= 10 ? 1 : 2);
    return `${val.toFixed(prec)} ${units[i]}`;
  };
  const totalStorageBytes = prerolls.reduce((sum, p) => sum + (Number(p.file_size) || 0), 0);

  // ============================================
  // Preroll Trash
  // ============================================
  const loadTrash = React.useCallback(async () => {
    setTrashLoading(true);
    setTrashError('');
    try {
      const res = await fetch(apiUrl('prerolls/trash'));
      if (!res.ok) throw new Error(`Server returned ${res.status}`);
      const data = await res.json();
      setTrashEntries(Array.isArray(data.entries) ? data.entries : []);
      setTrashBytes(Number(data.bytes) || 0);
      setTrashRetentionDays(Number(data.retention_days) || 0);
    } catch (e) {
      setTrashEntries([]);
      setTrashError(`Could not read the trash: ${e.message || e}`);
    } finally {
      setTrashLoading(false);
    }
  }, []);

  // Read the trash once at startup so the delete dialog can quote the real
  // retention window, then again every time the Trash page is opened. This
  // effect sits below loadTrash's definition; the mount effect near the top of
  // App() runs too early to reference it.
  const trashLoadedOnce = useRef(false);
  useEffect(() => {
    if (activeTab === 'library/trash' || !trashLoadedOnce.current) {
      trashLoadedOnce.current = true;
      loadTrash();
    }
  }, [activeTab, loadTrash]);

  const handleRestoreFromTrash = async (entry) => {
    const name = entry.display_name || entry.filename || 'this file';
    if (!await showConfirm(
      `Restore "${name}"?`,
      {
        title: 'Restore File',
        type: 'info',
        confirmText: 'Restore',
        details: [
          entry.original_path && { label: 'Restores to', value: entry.original_path },
          entry.deleted_at && { label: 'Deleted', value: formatTrashDate(entry.deleted_at) },
          entry.size_bytes && { label: 'Size', value: formatBytes(entry.size_bytes) },
        ].filter(Boolean),
      }
    )) return;

    setTrashBusyId(entry.entry_id);
    try {
      const res = await fetch(apiUrl(`prerolls/trash/${encodeURIComponent(entry.entry_id)}/restore`), { method: 'POST' });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.detail || `Server returned ${res.status}`);
      showAlert(`Restored "${name}".`, 'success');
      await loadTrash();
      fetchData();
    } catch (e) {
      showAlert(`Could not restore "${name}": ${e.message || e}`, 'error');
    } finally {
      setTrashBusyId(null);
    }
  };

  const handlePurgeTrashEntry = async (entry) => {
    const name = entry.display_name || entry.filename || 'this file';
    if (!await showConfirm(
      `Permanently delete "${name}"? This erases the video file for good and cannot be undone.`,
      {
        title: 'Delete Permanently',
        type: 'danger',
        confirmText: 'Delete Forever',
        details: [
          entry.original_path && { label: 'Came from', value: entry.original_path },
          entry.size_bytes && { label: 'Size', value: formatBytes(entry.size_bytes) },
        ].filter(Boolean),
      }
    )) return;

    setTrashBusyId(entry.entry_id);
    try {
      const res = await fetch(apiUrl(`prerolls/trash/${encodeURIComponent(entry.entry_id)}`), { method: 'DELETE' });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.detail || `Server returned ${res.status}`);
      showAlert(`Permanently deleted "${name}".`, 'success');
      await loadTrash();
    } catch (e) {
      showAlert(`Could not delete "${name}": ${e.message || e}`, 'error');
    } finally {
      setTrashBusyId(null);
    }
  };

  const handleEmptyTrash = async (expiredOnly) => {
    const count = trashEntries.length;
    if (!expiredOnly && count === 0) return;
    if (!await showConfirm(
      expiredOnly
        ? 'Delete every file in the trash that is past its retention window? This cannot be undone.'
        : `Permanently delete all ${count} file${count === 1 ? '' : 's'} in the trash? This cannot be undone.`,
      {
        title: expiredOnly ? 'Clear Expired' : 'Empty Trash',
        type: 'danger',
        confirmText: expiredOnly ? 'Clear Expired' : 'Empty Trash',
        details: expiredOnly
          ? [{ label: 'Removes', value: `Files older than ${trashRetentionDays} days` }]
          : [
              { label: 'Files', value: String(count) },
              { label: 'Frees', value: formatBytes(trashBytes) },
            ],
      }
    )) return;

    setTrashLoading(true);
    try {
      const res = await fetch(apiUrl(`prerolls/trash${expiredOnly ? '?expired_only=true' : ''}`), { method: 'DELETE' });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.detail || `Server returned ${res.status}`);
      const removed = Number(data.removed) || 0;
      showAlert(removed > 0
        ? `Removed ${removed} file${removed === 1 ? '' : 's'} from the trash.`
        : 'Nothing to remove.', 'success');
      await loadTrash();
    } catch (e) {
      showAlert(`Could not empty the trash: ${e.message || e}`, 'error');
      setTrashLoading(false);
    }
  };

  // Trash timestamps are stored as UTC ISO strings with a trailing Z; render them
  // in the browser's local time so "Deleted" matches the user's clock.
  const formatTrashDate = (iso) => {
    const t = Date.parse(iso || '');
    if (Number.isNaN(t)) return 'Unknown';
    return new Date(t).toLocaleString();
  };

  // Days left before a trashed file is purged, or null when retention is off.
  const trashDaysLeft = (entry) => {
    if (!trashRetentionDays) return null;
    const deleted = Date.parse(entry.deleted_at || '');
    if (Number.isNaN(deleted)) return null;
    const elapsedDays = (Date.now() - deleted) / 86400000;
    return Math.max(0, Math.ceil(trashRetentionDays - elapsedDays));
  };

  // Apply client-side filters in order: category/tags first, then match status
  const filteredPrerolls = React.useMemo(() => {
    let filtered = prerolls;
    
    // 1. Filter by category. Special string "uncategorized" matches prerolls with
    //    no categories at all (after v1.13.0 deletes a category, prerolls that had
    //    only that category land here).
    if (filterCategory === 'uncategorized') {
      filtered = filtered.filter(needsCategory);
    } else if (filterCategory) {
      const catId = parseInt(filterCategory);
      filtered = filtered.filter(p => prerollInCategory(p, catId));
    }
    
    // 2. Filter by tags
    if (filterTags && filterTags.trim()) {
      const searchTerms = filterTags.split(',').map(t => t.trim().toLowerCase()).filter(Boolean);
      filtered = filtered.filter(p => {
        const prerollTags = (p.tags || '').toLowerCase();
        const filename = (p.filename || '').toLowerCase();
        const displayName = (p.display_name || '').toLowerCase();
        return searchTerms.some(term => 
          prerollTags.includes(term) || filename.includes(term) || displayName.includes(term)
        );
      });
    }
    
    // 3. Filter by match status
    if (filterMatchStatus === 'matched') {
      filtered = filtered.filter(p => p.community_preroll_id);
    } else if (filterMatchStatus === 'unmatched') {
      filtered = filtered.filter(p => !p.community_preroll_id);
    }

    // 4. Hide generator output unless asked for. Skipped when the user has
    //    explicitly picked one of those categories, so choosing "NeX-Up Prerolls"
    //    from the category filter never returns an empty list.
    const selectedCategoryName = filterCategory && filterCategory !== 'uncategorized'
      ? String(categories.find(c => String(c.id) === String(filterCategory))?.name || '').toLowerCase()
      : '';
    const viewingGeneratedCategory = Boolean(selectedCategoryName) && NEXUP_GENERATED_CATEGORIES.includes(selectedCategoryName);
    if (!showNexupGeneratedInLibrary && !viewingGeneratedCategory) {
      filtered = filtered.filter(p => !isNexUpGeneratedPreroll(p));
    }

    // 4b. Same treatment for downloaded trailers. NeX-Up registers these as
    //     real Preroll rows when its storage path lives inside the prerolls
    //     folder, so hiding them has to happen here - the trailers toggle used
    //     to control only the separate read-only panel below the grid, which
    //     left "Hide NeX-Up trailers" looking broken for anyone whose trailers
    //     had been scanned in.
    const viewingTrailerCategory = Boolean(selectedCategoryName) && NEXUP_TRAILER_CATEGORIES.includes(selectedCategoryName);
    if (!showNexupTrailersInLibrary && !viewingTrailerCategory) {
      filtered = filtered.filter(p => !isNexUpTrailerPreroll(p));
    }

    // 5. Sort last, so the ordering applies to what survived the filters.
    return sortPrerolls(filtered, prerollSortField, prerollSortDirection);
  }, [prerolls, categories, filterCategory, filterTags, filterMatchStatus, showNexupGeneratedInLibrary, showNexupTrailersInLibrary, prerollSortField, prerollSortDirection]);

  const totalPrerolls = filteredPrerolls.length;
