  const handleGenerateDynamicPreroll = async () => {
    if (!dynamicPrerollSettings.server_name.trim()) {
      alert('Please enter your server name');
      return;
    }

    if (dynamicPrerollSettings.audioMode === 'custom' && !dynamicPrerollSettings.customAudioFilename) {
      alert('Please upload a custom soundtrack or choose Default soundtrack or No audio.');
      return;
    }
    
    setDynamicPrerollGenerating(true);
    try {
      const params = new URLSearchParams({
        template: dynamicPrerollSettings.template,
        server_name: dynamicPrerollSettings.server_name,
        duration: dynamicPrerollSettings.duration,
        theme: dynamicPrerollSettings.theme || 'midnight',
        language: dynamicPrerollSettings.language || 'en'
      });
      
      const res = await fetch(apiUrl(`/nexup/preroll/generate?${params.toString()}`), {
        method: 'POST'
      });
      const data = await res.json();
      
      if (data.success) {
        alert(`Generated "${data.template}" preroll successfully!`);
        setDynamicPrerollSettings(prev => ({
          ...prev,
          preroll_path: data.path
        }));
        // Refresh the list of generated prerolls
        loadGeneratedPrerolls();
      } else {
        alert('Failed to generate preroll: ' + (data.detail || data.message || 'Unknown error'));
      }
    } catch (err) {
      alert('Error generating preroll: ' + (err?.message || err));
    } finally {
      setDynamicPrerollGenerating(false);
    }
  };

  // Record the same animated canvas used by the live preview, then transcode it to MP4.
  const handleGenerateFromPreview = async () => {
    // Custom Message and QR Code never render the server name, so each gates on
    // the field it actually draws instead.
    const dynamicTemplate = dynamicPrerollSettings.template;
    if (dynamicTemplate === 'custom_text') {
      if (!String(dynamicPrerollSettings.customHeadline || '').trim() && !String(dynamicPrerollSettings.customSubtext || '').trim()) {
        alert('Enter a headline or a supporting line for the custom message.');
        return;
      }
    } else if (dynamicTemplate === 'qr_share') {
      if (!String(dynamicPrerollSettings.qrData || '').trim()) {
        alert('Enter the link or text the QR code should encode.');
        return;
      }
    } else if (!dynamicPrerollSettings.server_name.trim()) {
      alert('Please enter your server name');
      return;
    }

    if (dynamicPrerollSettings.audioMode === 'custom' && !dynamicPrerollSettings.customAudioFilename) {
      alert('Please upload a custom soundtrack or choose Default soundtrack or No audio.');
      return;
    }
    
    if (!previewContainerRef.current) {
      alert('Preview container not found.');
      return;
    }
    
    setDynamicPrerollGenerating(true);
    try {
      const selectedTheme = colorThemes?.[dynamicPrerollSettings.theme] || {};
      const selectedTemplate = dynamicPrerollTemplates.find(item => item.id === dynamicPrerollSettings.template);
      const logoUrl = dynamicPrerollSettings.customLogoFilename
        ? `${apiUrl('/nexup/preroll/logo-image')}?v=${encodeURIComponent(dynamicPrerollSettings.customLogoFilename)}`
        : null;
      const qrUrl = String(dynamicPrerollSettings.qrData || '').trim()
        ? buildQrUrl(apiUrl('/nexup/preroll/qr'), dynamicPrerollSettings)
        : null;
      const motionOptions = await prepareDynamicPrerollOptions({
        // The recording is what actually ships, so it has to use the chosen
        // face, not just the on-screen preview.
        settings: { ...dynamicPrerollSettings, fontStack: fontStackFor(nexupFonts, dynamicPrerollSettings.fontFamily) },
        theme: { ...selectedTheme },
        templateName: selectedTemplate?.name || 'Dynamic preroll',
        logoUrl,
        qrUrl,
      });
      const motionCapture = await recordDynamicPrerollAnimation(motionOptions);
      const imageData = motionCapture ? null : captureDynamicPrerollFrame(motionOptions);
      
      // Animated WebM is preferred; the still frame remains a compatibility fallback.
      const res = await fetch(apiUrl('/nexup/preroll/generate-from-preview'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          image_data: imageData,
          video_data: motionCapture?.videoData || null,
          video_mime_type: motionCapture?.mimeType || null,
          name: dynamicPrerollSettings.name?.trim() || null,
          duration: dynamicPrerollSettings.duration,
          template: dynamicPrerollSettings.template,
          server_name: dynamicPrerollSettings.server_name,
          theme: dynamicPrerollSettings.theme || 'custom',
          resolution: dynamicPrerollSettings.resolution || '1080',
          frame_rate: dynamicPrerollSettings.frameRate || 30,
          quality: dynamicPrerollSettings.renderQuality || 'high',
          font_scale: dynamicPrerollSettings.fontScale || 1,
          title_color: dynamicPrerollSettings.titleColor || null,
          subject_color: dynamicPrerollSettings.subjectColor || null,
          audio_mode: dynamicPrerollSettings.audioMode || 'none',
          custom_headline: dynamicPrerollSettings.customHeadline || null,
          custom_subtext: dynamicPrerollSettings.customSubtext || null,
          qr_data: dynamicPrerollSettings.qrData || null,
          qr_caption: dynamicPrerollSettings.qrCaption || null
        })
      });
      
      const data = await res.json();
      
      if (data.success) {
        alert('Generated preroll from preview successfully!');
        setDynamicPrerollSettings(prev => ({
          ...prev,
          preroll_path: data.path
        }));
        // Refresh the list of generated prerolls
        loadGeneratedPrerolls();
      } else {
        alert('Failed to generate preroll: ' + (data.detail || data.message || 'Unknown error'));
      }
    } catch (err) {
      console.error('Error generating from preview:', err);
      alert('Error generating preroll from preview: ' + (err?.message || err));
    } finally {
      setDynamicPrerollGenerating(false);
    }
  };

